//
// Tests need TEST_DATABASE_URL (an admin connection to the test server).
// Without it they skip, unless REQUIRE_DB=1, which make test sets: then a
// missing database fails the run instead of silently skipping it.
package testdb

import (
	"context"
	"crypto/rand"
	"database/sql"
