[
  {
    "name": "istanbul_cart_abandoners",
    "category": "cart_abandoners",
    "brief": "Son 30 günde sepetine ürün ekleyip alışveriş yapmayan İstanbul'daki kullanıcılara %30 indirim hatırlatması gönder.",
    "expect": {
      "match": "all",
      "conditions": [
        { "kind": "enum_attribute", "field": "city", "op": "eq", "value": "istanbul" },
        { "kind": "event", "event": "cart_add", "within_days": 30, "negate": false },
        { "kind": "event", "event": "purchase", "within_days": 30, "negate": true }
      ],
      "must_include": {
        "sms": ["istanbul_cart_no_purchase"],
        "email": ["istanbul_cart_no_purchase", "istanbul_cart_no_purchase_no_sms_consent"]
      },
      "must_exclude": {
        "sms": ["istanbul_cart_purchased", "ankara_cart_no_purchase", "istanbul_cart_no_purchase_no_sms_consent", "istanbul_cart_no_purchase_no_consent"],
        "email": ["istanbul_cart_purchased", "ankara_cart_no_purchase", "istanbul_cart_no_purchase_no_consent"]
      },
      "audience": { "min": 300, "max": 340 },
      "language": "tr",
      "require_variable": "campaign_url"
    }
  },
  {
    "name": "ankara_cart_abandoners",
    "category": "negation",
    "brief": "Ankara'da son 30 günde sepete ürün ekleyip satın almayan kullanıcılara ücretsiz kargo hatırlatması gönder.",
    "expect": {
      "match": "all",
      "conditions": [
        { "kind": "enum_attribute", "field": "city", "op": "eq", "value": "ankara" },
        { "kind": "event", "event": "cart_add", "within_days": 30, "negate": false },
        { "kind": "event", "event": "purchase", "within_days": 30, "negate": true }
      ],
      "must_include": {
        "sms": ["ankara_cart_no_purchase"],
        "email": ["ankara_cart_no_purchase"]
      },
      "must_exclude": {
        "sms": ["istanbul_cart_no_purchase", "istanbul_cart_purchased"],
        "email": ["istanbul_cart_no_purchase", "istanbul_cart_purchased", "istanbul_cart_no_purchase_no_sms_consent"]
      },
      "language": "tr",
      "require_variable": "campaign_url"
    }
  },
  {
    "name": "istanbul_recent_buyers",
    "category": "negation",
    "brief": "Son 7 günde alışveriş yapan İstanbul'daki müşterilere teşekkür mesajı ve bir sonraki alışverişte geçerli %10 indirim gönder.",
    "expect": {
      "match": "all",
      "conditions": [
        { "kind": "enum_attribute", "field": "city", "op": "eq", "value": "istanbul" },
        { "kind": "event", "event": "purchase", "within_days": 7, "negate": false }
      ],
      "must_include": {
        "sms": ["istanbul_cart_purchased"],
        "email": ["istanbul_cart_purchased"]
      },
      "must_exclude": {
        "sms": ["istanbul_cart_no_purchase", "ankara_cart_no_purchase"],
        "email": ["istanbul_cart_no_purchase", "ankara_cart_no_purchase", "istanbul_cart_no_purchase_no_sms_consent"]
      },
      "language": "tr",
      "require_variable": "campaign_url"
    }
  },
  {
    "name": "istanbul_cart_adders_consent",
    "category": "consent",
    "brief": "İstanbul'da son 30 günde sepetine ürün ekleyen herkese yeni sezon ürünlerini duyur.",
    "expect": {
      "match": "all",
      "conditions": [
        { "kind": "enum_attribute", "field": "city", "op": "eq", "value": "istanbul" },
        { "kind": "event", "event": "cart_add", "within_days": 30, "negate": false }
      ],
      "must_include": {
        "sms": ["istanbul_cart_no_purchase", "istanbul_cart_purchased"],
        "email": ["istanbul_cart_no_purchase", "istanbul_cart_purchased", "istanbul_cart_no_purchase_no_sms_consent"]
      },
      "must_exclude": {
        "sms": ["ankara_cart_no_purchase", "istanbul_cart_no_purchase_no_sms_consent", "istanbul_cart_no_purchase_no_consent"],
        "email": ["ankara_cart_no_purchase", "istanbul_cart_no_purchase_no_consent"]
      },
      "language": "tr",
      "require_variable": "campaign_url"
    }
  },
  {
    "name": "izmir_antalya_or_recent_cart",
    "category": "any_match",
    "brief": "İzmir veya Antalya'da yaşayan ya da son 7 günde sepetine ürün ekleyen kullanıcılara yaz indirimini duyur.",
    "expect": {
      "match": "any",
      "conditions": [
        { "kind": "enum_attribute", "field": "city", "op": "in", "values": ["izmir", "antalya"] },
        { "kind": "event", "event": "cart_add", "within_days": 7, "negate": false }
